#include "Reader.h"
#include "../../../Sources/AtomicImageWriter.h"
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
namespace RetroMediaLab::MediaEngine::Xdvdfs {
namespace {std::string normalized(std::string_view extension){return !extension.empty()&&extension.front()!=Constants::ExtensionSeparator?std::string(1,Constants::ExtensionSeparator)+std::string(extension):std::string(extension);}}
const WriterCapabilities& Writer::capabilities()const{using namespace Constants;static const WriterCapabilities caps{std::string(WriterId),{std::string(FormatId)},{std::string(Extension)},{RepresentationKind::OpticalTracks},false};return caps;}
bool Writer::canWrite(const MediaDocument& document,std::string_view format,std::string_view extension)const{using namespace Constants;const auto* image=dynamic_cast<const OpticalImage*>(&document.representation());if(document.mediaKind()!=MediaKind::Optical||!supportsTarget(format,normalized(extension))||!image||!image->options().tracks||image->options().tracks->size()!=1)return false;const auto& value=image->options().tracks->front()->options();return value.mode==OpticalTrackMode::Mode1Data2048&&value.storedSectorSize==SectorBytes&&value.userDataOffset==0&&value.userDataLength==SectorBytes&&value.sectorCount>DescriptorSector;}
std::future<std::vector<std::filesystem::path>> Writer::writeAsync(std::shared_ptr<const MediaDocument> document,std::filesystem::path path,std::string format,std::stop_token token)const{return std::async(std::launch::deferred,[document=std::move(document),path=std::move(path),format=std::move(format),token]{checkCancellation(token);if(!document)throw MediaError(DiagnosticCode::HardDiskRawNullDocument);const auto raw=path.extension().u8string();if(!Writer{}.canWrite(*document,format,std::string(raw.begin(),raw.end())))throw MediaError(DiagnosticCode::XdvdfsWrite);const auto track=dynamic_cast<const OpticalImage&>(document->representation()).options().tracks->front();writeAtomicImage(path,[track](const auto& output,auto stop){for(std::int64_t sector=0;sector<track->sectorCount();++sector){checkCancellation(stop);output(track->readStoredSectorAsync(sector,stop).get());}},token);return std::vector<std::filesystem::path>{path};});}
}
